const N = Math.round(p.puffs), H = api.h, W = api.w;
const src = W * 0.5, base = H - 1;
const span = H - 2;

// --- rising plume: many overlapping puffs so it reads as one continuous column ---
const total = Math.max(10, N * 3);
for (let i = 0; i < total; i++) {
  const ph = (api.t + i / total) % 1;
  const wob = api.rnd(i * 7 + 1) * 2 - 1;
  const y = base - ph * span;
  const climb = ph;
  // lateral drift: grows with height, wraps cleanly through sin(2pi t)
  const x = src
    + wob * p.drift * climb * climb * 0.8
    + Math.sin(2 * Math.PI * (api.t + i * 0.37)) * p.drift * 0.35 * climb;
  // starts tight at the mouth, swells as it rises
  const r = 0.9 + climb * p.girth * (0.7 + api.rnd(i * 13 + 5) * 0.5);
  const cut = p.fade;
  let a = climb < 0.05 ? climb / 0.05 : 1;
  if (climb > cut) {
    const e = (climb - cut) / Math.max(0.001, 1 - cut);
    a *= Math.max(0, 1 - e * e * 0.6 - e * 0.4);
  }
  a *= p.intensity * 0.8;
  if (a <= 0.02) continue;
  // greys only, and lighter as it cools and thins upward
  const ci = climb < 0.25 ? 2 : climb < 0.55 ? 1 : 0;
  const cx = Math.round(x), cy = Math.round(y);
  api.blob(cx, cy, r, ci, a);
  // bridge toward the next puff so the column is unbroken, not a string of beads
  const gy = Math.round(y + span / total * 0.5);
  api.blob(Math.round(x), gy, r * 0.85, ci, a * 0.85);
  const gy2 = Math.round(y - span / total * 0.5);
  api.blob(Math.round(x), gy2, r * 0.8, ci, a * 0.75);
  // a lighter cap on the upper side of each puff, the usual smoke read
  if (r > 1.3) api.blob(cx, cy - 1, r * 0.5, ci > 0 ? ci - 1 : 0, a * 0.55);
}

// --- solid root at the chimney mouth ---
for (let k = 0; k < 3; k++) {
  const ry = base - k;
  const jog = k === 2 ? (Math.sin(2 * Math.PI * api.t) > 0 ? 1 : 0) : 0;
  api.blob(src + jog, ry, 1.0 + k * 0.3, 2, p.intensity * (0.8 - k * 0.1));
}

// --- evaporation: the top comes apart into scattered pixels that fade to nothing ---
const wisps = 14;
for (let k = 0; k < wisps; k++) {
  const ph2 = (api.t * 0.8 + k / wisps) % 1;
  // wisps only live in the top band, above the fade point
  const start = Math.max(0.45, p.fade * 0.9);
  const climb2 = start + ph2 * (1 - start);
  const yy = Math.round(base - climb2 * span);
  const wob2 = api.rnd(k * 11 + 9) * 2 - 1;
  const xx = Math.round(src
    + wob2 * p.drift * climb2 * climb2 * 0.9
    + Math.sin(2 * Math.PI * (api.t + k * 0.21)) * (1 + p.drift * 0.3));
  const spread = 1 + Math.round((1 - ph2) * 0 + ph2 * (1 + p.girth * 0.5));
  const aa = (1 - ph2) * (1 - ph2) * 0.5 * p.intensity;
  if (aa <= 0.02) continue;
  api.px(xx, yy, 0, aa);
  api.px(xx + (k % 2 ? spread : -spread), yy + (k % 3 === 0 ? -1 : 0), 0, aa * 0.7);
  if (ph2 < 0.5) api.px(xx + (k % 2 ? -1 : 1), yy + 1, 1, aa * 0.6);
}
